const JOURNAL_KEY='learning-garden-journal-v1';
const JOURNAL_TYPES={thought:{label:'Thoughts',icon:'✎',color:'#eee7f5'},achievement:{label:'Achievement',icon:'✦',color:'#f5edcb'},learning:{label:'Learning',icon:'❧',color:'#e7eddf'}};
let journalEntries=[],journalStorageOK=true,journalType='all',journalMonth='all',journalArchived=false;
try{const stored=localStorage.getItem(JOURNAL_KEY);if(stored)journalEntries=validateJournal(JSON.parse(stored))}catch{journalStorageOK=false}
const pythonLearningEntry={"id": "python-syntax-2026-10-25", "type": "learning", "date": "2026-10-25", "title": "Python syntax — what I learned today", "text": "My Python syntax reference from today.\n\n| Syntax | Meaning | Example |\n| --- | --- | --- |\n| `print()` | Displays a value or result | `print(100)` |\n| `=` | Assigns a value to a variable | `age = 25` |\n| `+` | Addition | `10 + 5` |\n| `-` | Subtraction | `10 - 5` |\n| `*` | Multiplication | `10 * 5` |\n| `/` | Division | `10 / 5` |\n| `**` | Power or exponent | `time ** 2` |\n| `[]` | Creates a list | `vendors = []` |\n| `\" \" or ' '` | Represents text (a string) | `name = \"Microsoft\"` |\n| `,` | Separates items | `[\"SAP\", \"Oracle\"]` |\n| `for` | Starts a loop | `for vendor in vendors:` |\n| `in` | Used in a for loop to iterate through a collection | `for vendor in vendors:` |\n| `:` | Begins an indented code block after a for statement | `for x in items:` |\n| `Indentation` | Spaces showing which code belongs inside a block | `    print(vendor)` |\n| `.lower()` | Converts text to lowercase | `\"SAP\".lower()` |\n| `.replace()` | Replaces part of a string | `name.replace(\" Corp\", \"\")` |\n| `.append()` | Adds an item to the end of a list | `vendors.append(\"SAP\")` |\n| `set()` | Creates a set containing unique values | `set(vendors)` |\n| `len()` | Counts the number of items | `len(vendors)` |\n| `#` | Adds a comment ignored by Python | `# My first code` |\n\nPractice: normalize vendor names and keep unique values.\n\n```python\nvendors = [\"SAP\", \"Oracle\", \"SAP\"]\ncleaned = []\nfor vendor in vendors:\n    cleaned.append(vendor.lower())\nprint(set(cleaned))\n```\n\nCorrections: the two #ERROR! cells were = and +. Strings use quotation marks. \"SAP\".lower() works on a string; SAP.lower() needs a variable named SAP to exist first. The variable time must also be defined before using time ** 2.", "archived": false, "createdAt": "2026-10-25T00:00:00Z", "updatedAt": "2026-10-25T00:00:00Z"};
if(journalStorageOK&&!journalEntries.some(e=>e.id===pythonLearningEntry.id)){journalEntries.push(pythonLearningEntry);persistJournal()}
function validJournalDate(date){return typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(Date.parse(date+'T00:00:00Z'))&&new Date(date+'T00:00:00Z').toISOString().slice(0,10)===date}
function validateJournal(value){if(!Array.isArray(value)||value.length>10000)throw Error('Invalid journal');const ids=new Set();return value.map(e=>{if(!e||typeof e.id!=='string'||ids.has(e.id)||!Object.hasOwn(JOURNAL_TYPES,e.type)||!validJournalDate(e.date)||typeof e.title!=='string'||e.title.length>180||typeof e.text!=='string'||!e.text.trim()||e.text.length>20000)throw Error('Invalid entry');ids.add(e.id);return {id:e.id,type:e.type,date:e.date,title:e.title,text:e.text,archived:!!e.archived,createdAt:typeof e.createdAt==='string'?e.createdAt:'',updatedAt:typeof e.updatedAt==='string'?e.updatedAt:''}})}
function persistJournal(){try{localStorage.setItem(JOURNAL_KEY,JSON.stringify(journalEntries));journalStorageOK=true}catch{journalStorageOK=false}}
function mergeJournal(incoming){if(!incoming)return;const map=new Map(journalEntries.map(e=>[e.id,e]));incoming.forEach(e=>map.set(e.id,e));journalEntries=[...map.values()];persistJournal()}
function entryTitle(e){return e.title||e.text.split('\n')[0].slice(0,70)}
function renderJournal(){const all=journalEntries.filter(e=>e.archived===journalArchived);const matches=all.filter(e=>(journalType==='all'||e.type===journalType)&&(journalMonth==='all'||e.date.startsWith(journalMonth))&&[e.title,e.text,JOURNAL_TYPES[e.type].label].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));const months=[...new Set(all.map(e=>e.date.slice(0,7)))].sort().reverse();$('breadcrumb').textContent='Journal';$('search').placeholder='Search your journal…';$('search').setAttribute('aria-label','Search journal entries');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='journal'));$('content').innerHTML=`<div class="intro"><div><div class="eyebrow">A RECORD OF YOUR OWN GROWTH</div><h1>My journal.</h1><p class="muted">Thoughts, small wins, and things you don’t want to forget.</p></div><button id="writeJournal" class="primary">＋ Write an entry</button></div><div class="journal-intro"><div><span class="journal-flower" aria-hidden="true">✳</span><h2>You’re making progress.<br>Give it a little space.</h2><p>It can be a thought, an achievement, or something you learned. A few honest lines are enough.</p></div><div class="journal-prompts"><button data-journal-prompt="thought">✎ What’s on my mind?</button><button data-journal-prompt="achievement">✦ A win I want to remember</button><button data-journal-prompt="learning">❧ Something I figured out</button></div></div><div class="journal-tools"><div class="filters" style="margin:0">${[['all','All entries'],...Object.entries(JOURNAL_TYPES).map(([k,v])=>[k,v.label])].map(([k,label])=>`<button data-journal-type="${k}" class="${journalType===k?'selected':''}">${label}</button>`).join('')}</div><select class="filter-select" id="journalMonth" aria-label="Filter journal by month"><option value="all">All months</option>${months.map(m=>`<option value="${m}" ${journalMonth===m?'selected':''}>${monthLabel(m)}</option>`).join('')}</select><button class="textbtn" id="toggleJournalArchive">${journalArchived?'← Current entries':'Archived entries'}</button></div><div class="journal-count">${journalArchived?'Archived · ':''}${matches.length} ${matches.length===1?'entry':'entries'}</div><div class="journal-list">${matches.map(e=>{const type=JOURNAL_TYPES[e.type];return `<article class="journal-entry"><div class="journal-date"><strong>${new Date(e.date+'T12:00:00').getDate()}</strong><span>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short',year:'numeric'})}</span></div><div class="journal-entry-content"><span class="tag" style="background:${type.color}">${type.icon} ${type.label}</span><h3>${esc(entryTitle(e))}</h3><p>${esc(e.text.slice(0,230))}${e.text.length>230?'…':''}</p><div class="journal-entry-actions"><button class="textbtn" data-journal-read="${esc(e.id)}">Read entry ↗</button><button class="textbtn" data-journal-edit="${esc(e.id)}">Edit</button></div></div></article>`}).join('')||`<div class="journal-empty"><span aria-hidden="true">✎</span><h2>${journalArchived?'Nothing archived.':all.length?'Nothing matches just yet.':'This page is waiting for your story.'}</h2><p>${journalArchived?'Archived entries will appear here.':all.length?'Try a different filter or search.':'Start with one thought, one small achievement, or one thing you learned today.'}</p>${!journalArchived?'<button data-journal-prompt="thought">Write a few lines ↗</button>':''}</div>`}</div><footer><span>${journalStorageOK?'Your journal saves in this browser.':'Browser storage unavailable. Export a backup to keep your entries.'} Backups include your journal.</span><span><button class="textbtn" id="export">Export backup ↓</button><button class="textbtn" id="import">Import backup ↑</button></span></footer>`}
function showJournalEditor(id,type='thought'){const e=journalEntries.find(e=>e.id===id)||{type,date:localDay(),title:'',text:''};$('journalId').value=e.id||'';$('journalEntryDate').value=e.date;$('journalEntryType').innerHTML=Object.entries(JOURNAL_TYPES).map(([k,v])=>`<option value="${k}" ${e.type===k?'selected':''}>${v.label}</option>`).join('');$('journalEntryTitle').value=e.title;$('journalEntryText').value=e.text;$('journalEntryError').textContent='';$('journalEditorTitle').textContent=e.id?'Your words, in your own time.':'A few lines for yourself.';$('archiveJournalEntry').classList.toggle('hidden',!e.id);$('archiveJournalEntry').textContent=e.archived?'Restore entry':'Archive entry';resetLearningPreview('journalEntryText');$('journalEditor').showModal()}
function showJournalReader(id){const e=journalEntries.find(e=>e.id===id);if(!e)return;const type=JOURNAL_TYPES[e.type];$('journalReadContent').innerHTML=`<div class="section-head" style="margin-top:0"><span class="tag" style="background:${type.color}">${type.icon} ${type.label} · ${taskDate(e.date)}</span><button data-close-journal="journalReader" aria-label="Close journal entry">✕</button></div><h2 style="line-height:1.35">${esc(entryTitle(e))}</h2><div class="journal-full-text">${renderLearningText(e.text)}</div><div class="actions"><button data-close-journal="journalReader">Close</button><button class="primary" data-journal-edit="${esc(e.id)}">Edit entry</button></div>`;$('journalReader').showModal()}
function saveJournalDraft(draft){if(!validJournalDate(draft.date)||!Object.hasOwn(JOURNAL_TYPES,draft.type)||!draft.text.trim())throw Error('Write an entry and choose a valid date.');const existing=journalEntries.find(e=>e.id===draft.id),now=new Date().toISOString();const e={id:existing?.id||newId(),date:draft.date,type:draft.type,title:draft.title.trim(),text:draft.text.trim(),createdAt:existing?.createdAt||now,updatedAt:now,archived:existing?.archived||false};const i=journalEntries.findIndex(x=>x.id===e.id);if(i>=0)journalEntries[i]=e;else journalEntries.push(e);persistJournal();return e}
function setupJournal(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='writeJournal')showJournalEditor();if(b.dataset.journalPrompt)showJournalEditor(null,b.dataset.journalPrompt);if(b.dataset.journalRead)showJournalReader(b.dataset.journalRead);if(b.dataset.journalEdit){$('journalReader').close();showJournalEditor(b.dataset.journalEdit)}if(b.dataset.journalType){journalType=b.dataset.journalType;render()}if(b.id==='toggleJournalArchive'){journalArchived=!journalArchived;journalMonth='all';render()}if(b.dataset.closeJournal)$(b.dataset.closeJournal).close();if(b.id==='archiveJournalEntry'){const entry=journalEntries.find(e=>e.id===$('journalId').value);entry.archived=!entry.archived;entry.updatedAt=new Date().toISOString();persistJournal();$('journalEditor').close();render();toast(entry.archived?'Entry archived. You can restore it from Archived entries.':'Entry restored')}});document.addEventListener('change',e=>{if(e.target.id==='journalMonth'){journalMonth=e.target.value;render()}});$('journalEntryForm').addEventListener('submit',e=>{e.preventDefault();try{const entry=saveJournalDraft({id:$('journalId').value,date:$('journalEntryDate').value,type:$('journalEntryType').value,title:$('journalEntryTitle').value,text:$('journalEntryText').value});$('journalEditor').close();journalMonth='all';journalType='all';journalArchived=entry.archived;render();toast('Entry saved')}catch(error){$('journalEntryError').textContent=error.message}})}
